INSERT INTO public.water_body_location_checks(water_body_id,provider,status,candidate_name,candidate_latitude,candidate_longitude,provider_place_id,match_confidence,evidence_url,checked_at,reviewer_notes) SELECT b.water_body_id,'openstreetmap','verified',b.candidate_name,b.latitude,b.longitude,'osm:'||b.osm_type||':'||b.osm_id,CASE WHEN b.type_score=3 THEN 0.97 ELSE 0.92 END,CASE WHEN b.osm_type='W' THEN 'https://www.openstreetmap.org/way/' WHEN b.osm_type='N' THEN 'https://www.openstreetmap.org/node/' WHEN b.osm_type='R' THEN 'https://www.openstreetmap.org/relation/' ELSE 'https://www.openstreetmap.org/' END||b.osm_id,now(),'Exact distinctive water-name token + province match; type-compatible OSM water feature; general waterbody location only, not a fishing-access point. Photon lookup: '||b.query_url FROM verified_batch_01 b;
