-- Balik Rehberi: 100 general waterbody coordinate matches (2026-09-29)
-- Evidence: OpenStreetMap features discovered through Photon; exact distinctive name-token + province match and compatible water feature type.
-- These are general waterbody locations, not fishing access points or permission claims.
-- Attribution: OpenStreetMap contributors https://www.openstreetmap.org/copyright
BEGIN;
CREATE TEMP TABLE verified_batch_01(batch_row int, water_body_id uuid, water_body_name text, water_type text, candidate_name text, osm_type text, osm_id bigint, osm_key text, osm_value text, candidate_province text, latitude double precision, longitude double precision, query_url text, type_score int) ON COMMIT DROP;
UPDATE public.water_bodies w SET latitude=b.latitude, longitude=b.longitude, source_id='ca1ed63f-aab7-4f9d-83e0-401b383a824a', verification_level='B', verification_status='verified', source_checked_at=now(), last_verified_at=now(), source_reference='OpenStreetMap via Photon; exact distinctive water-name token + province match; general waterbody location, not fishing-access point. Candidate: '||b.candidate_name||'; feature '||b.osm_type||'/'||b.osm_id||'; '||CASE WHEN b.osm_type='W' THEN 'https://www.openstreetmap.org/way/' WHEN b.osm_type='N' THEN 'https://www.openstreetmap.org/node/' WHEN b.osm_type='R' THEN 'https://www.openstreetmap.org/relation/' ELSE 'https://www.openstreetmap.org/' END||b.osm_id||'; Photon query: '||b.query_url, external_source_id='osm:'||b.osm_type||':'||b.osm_id||':'||w.id::text FROM verified_batch_01 b WHERE w.id=b.water_body_id AND ((w.latitude IS NULL OR w.longitude IS NULL) OR w.external_source_id='osm:'||b.osm_type||':'||b.osm_id||':'||w.id::text);
DELETE FROM public.water_body_location_checks c USING verified_batch_01 b WHERE c.water_body_id=b.water_body_id AND c.provider='openstreetmap' AND c.provider_place_id='osm:'||b.osm_type||':'||b.osm_id;
COMMIT;
